package batch

import (
    "context"
    "fmt"
    "time"
)

func Collect(ctx context.Context, in <-chan Item, max int, wait time.Duration) ([]Item, error) {
    if max <= 0 || wait <= 0 { return nil, fmt.Errorf("invalid batch limits") }
    var first Item
    var ok bool
    select {
    case <-ctx.Done(): return nil, ctx.Err()
    case first, ok = <-in:
        if !ok { return nil, fmt.Errorf("input closed") }
    }
    out := []Item{first}
    timer := time.NewTimer(wait)
    defer timer.Stop()
    for len(out) < max {
        select {
        case <-ctx.Done(): return nil, ctx.Err()
        case <-timer.C: return out, nil
        case item, ok := <-in:
            if !ok { return out, nil }
            out = append(out, item)
        }
    }
    return out, nil
}
